CREATE FUNCTION GET_IP RETURN VARCHAR2 IS
BEGIN
  RETURN SYS_CONTEXT('USERENV','IP_ADDRESS');
END;

CREATE FUNCTION GET_TERMINAL RETURN VARCHAR2 IS
BEGIN
  RETURN SYS_CONTEXT('USERENV','TERMINAL');
END;

CREATE FUNCTION PATH (MD CHAR) RETURN CHAR IS
L LOCATION.LOC%TYPE;
BEGIN
  SELECT LOC INTO L
  FROM LOCATION
  WHERE MODULE = MD;
  RETURN L;
EXCEPTION WHEN NO_DATA_FOUND THEN
 RETURN 'farrukh@faitsolutions.com';
END;

CREATE FUNCTION GET_URDU ( P_CID NUMBER ) RETURN CHAR IS
v_URDU_DESC URDU_CONFIG.URDU_DESC%TYPE;
BEGIN

  SELECT URDU_DESC INTO v_URDU_DESC
  FROM   URDU_CONFIG
  WHERE  CID = p_CID;

  RETURN v_URDU_DESC;
EXCEPTION
 WHEN NO_DATA_FOUND THEN
 RETURN NULL;

END;

