CREATE FUNCTION GET_MAX_USER_ID RETURN NUMBER IS
    MAX_ID  NUMBER;
BEGIN
    SELECT NVL(MAX(USER_ID),0)+1
    INTO MAX_ID
    FROM UM_USERS;
    RETURN MAX_ID;
END GET_MAX_USER_ID;

CREATE FUNCTION GET_MAX_MENU_ID RETURN NUMBER IS
    MAX_ID  NUMBER;
BEGIN
    SELECT NVL(MAX(MENU_ID),0)+1
    INTO MAX_ID
    FROM UM_MENU;
    RETURN MAX_ID;
END GET_MAX_MENU_ID;

