CREATE FUNCTION GET_ACCOUNT_CITY_URDU (p_CODE  CHAR) RETURN CHAR IS
v_CHDESC VARCHAR2(1000);
BEGIN
  SELECT C.CHDESC_URDU||' '||CT.CNAME_URDU INTO v_CHDESC
  FROM   CHART C,CITY CT
  WHERE C.FK_CCODE = CT.PK_CCODE
  AND   C.CHCODE   = p_CODE;

  RETURN v_CHDESC;

EXCEPTION
	WHEN NO_DATA_FOUND THEN
RETURN '--';

END;

